"@media (max-width:980px){.top{align-items:flex-start;padding:8px 10px}.brand{display:grid;grid-template-columns:42px minmax(0,1fr);column-gap:10px;row-gap:2px;align-items:start;width:100%}.logo{margin-top:0;grid-column:1;grid-row:1;flex:none}.brandText{min-width:0;grid-column:2;grid-row:1;width:100%}.brandHelp{grid-column:1 / span 2;grid-row:2;width:100%;padding-top:0}.title{font-size:15px;line-height:1.15}.sub{font-size:11px;line-height:1.3}.miniHelp{font-size:11px;line-height:1.35}.top #authRow{margin-top:4px;width:100%}.rightHeader{display:grid;grid-template-columns:70px 1fr;grid-template-areas:'crumbs controls';column-gap:6px;row-gap:4px;align-items:start;padding:6px 8px}.rightHeader .crumbs{grid-area:crumbs;gap:4px;align-self:start;min-width:0}.rightHeader .row{grid-area:controls;display:grid;grid-template-columns:1fr 1fr 1fr 1fr;grid-template-rows:32px 34px;gap:4px;align-items:stretch;width:100%}.rightHeader .row #search{grid-column:1 / span 4;grid-row:1;height:32px;font-size:11px;padding:5px 9px;min-width:0;width:100%}.rightHeader .row #btnHome{grid-column:1;grid-row:2;height:34px}.rightHeader .row #btnSubject{grid-column:2;grid-row:2;height:34px}.rightHeader .row #btnAll{grid-column:3;grid-row:2;height:34px}.rightHeader .row #btnTrending{display:none}.rightHeader .row #btnGlobal{display:block}.rightHeader .row #btnStudio{grid-column:4;grid-row:2;height:34px}.rightHeader .row #btnInstallApp{display:none}.rightHeader .row .btn{font-size:10px;padding:3px 4px;border-radius:10px;line-height:1.0}.rightHeader .row .inp{font-size:11px;border-radius:10px}.crumbs{gap:4px}.crumb{padding:4px 8px;font-size:10px}.item{padding:8px}.itemTitle{font-size:14px}.itemMeta{font-size:11px}.itemBtns{display:flex;flex-wrap:nowrap;justify-content:flex-start;align-items:center;gap:4px;max-width:none}.itemBtns .pill{padding:4px 6px;font-size:10px;line-height:1.05;white-space:nowrap}.filterBar{gap:6px;padding:8px;border-radius:14px}.filterLabel{font-size:11px}.filterSelect{padding:7px 9px;font-size:12px;border-radius:10px}.filterSummary{font-size:11px}.grid>.card:first-child #btnRew,.grid>.card:first-child #btnFwd{display:none}.grid>.card:first-child .controls{gap:4px;flex-wrap:wrap;justify-content:flex-start;align-items:center}.grid>.card:first-child .btn{padding:4px 7px;font-size:10px;line-height:1.05;min-height:28px}.grid>.card:first-child .pill{padding:4px 6px;font-size:10px;line-height:1.05;min-height:28px}.grid>.card:first-child #btnShuffle,.grid>.card:first-child #btnRepeat{font-size:0}.grid>.card:first-child #btnShuffle::after{content:'Shuffle';font-size:10px}.grid>.card:first-child #btnRepeat::after{content:'Repeat';font-size:10px}#bottomMiniPlayer{display:block;position:fixed;left:0;right:0;bottom:max(0px,env(safe-area-inset-bottom,0px));width:100%;margin:0;z-index:9999;border-top:1px solid rgba(255,191,0,.26);border-left:none;border-right:none;border-bottom:none;border-radius:0;background:linear-gradient(180deg, rgba(20,20,20,.99), rgba(0,0,0,1));box-shadow:0 -10px 26px rgba(0,0,0,.65);padding:8px 10px calc(8px + env(safe-area-inset-bottom,0px)) 10px}body{padding-bottom:92px}#bottomMiniPlayer .bmpRow{display:flex;align-items:center;gap:8px}#bottomMiniPlayer .bmpArt{width:38px;height:38px;border-radius:8px;border:1px solid rgba(255,191,0,.22);object-fit:cover;background:#111}#bottomMiniPlayer .bmpMeta{min-width:0;flex:1}#bottomMiniPlayer .bmpTitle{font-size:12px;color:var(--text);font-weight:900}#bottomMiniPlayer .bmpSub{font-size:10px;color:var(--muted)}#bottomMiniPlayer .bmpBtn{-webkit-appearance:none;appearance:none;border:1px solid rgba(255,191,0,.34);background:linear-gradient(180deg, rgba(255,191,0,.16), rgba(255,191,0,.08));color:var(--gold2);border-radius:10px;padding:0;width:32px;height:32px;min-width:32px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900;line-height:1;box-shadow:inset 0 0 0 1px rgba(255,218,106,.05)}#bottomMiniPlayer .bmpBar{height:3px;margin-top:6px;border-radius:999px;background:rgba(255,255,255,.10);overflow:hidden}#bottomMiniPlayer .bmpFill{height:100%;width:0%;background:var(--gold)}}",
"@media (min-width:981px){.top{flex-wrap:nowrap;align-items:center}.brand{flex-wrap:nowrap;min-width:0;flex:1}.brandText{min-width:0;flex:1}.brandHelp{display:none}.top #authRow{margin-left:auto;flex:0 0 auto;min-width:auto;width:auto;display:flex;flex-direction:row;align-items:center;justify-content:flex-end}.top #authRow .row{width:auto}.top #authRow .chip{width:auto !important;max-width:520px}.rightHeader{align-items:flex-start}.rightHeader .crumbs{flex:0 0 100%}.rightHeader .row{width:100%;display:flex;flex-wrap:wrap;justify-content:flex-start;align-items:center;gap:10px}.rightHeader .row #search{flex:0 0 220px;min-width:220px}.rightHeader .row .btn{flex:0 0 auto}}",
".ss-contact-box{position:fixed;right:24px;top:110px;width:320px;max-width:calc(100vw - 32px);padding:16px;border:1px solid rgba(255,191,0,.35);border-radius:16px;background:#111;z-index:9999;box-shadow:0 10px 30px rgba(0,0,0,.45)}",
".ss-contact-title{color:#ffbf00;font-weight:800;font-size:18px;margin-bottom:12px}",
