"        html += \"<div class=\\\"itemMeta\\\" style=\\\"margin-top:8px\\\">Albums Missing Cover: \" + escapeHtml2(String(health.albums_missing_cover_count || 0)) + \"</div>\";",
"        html += \"<div class=\\\"itemMeta\\\">Albums With Zero Tracks: \" + escapeHtml2(String(health.albums_zero_tracks_count || 0)) + \"</div>\";",
"        html += \"<div class=\\\"itemMeta\\\">Tracks Missing Album Link: \" + escapeHtml2(String(health.tracks_missing_album_link_count || 0)) + \"</div>\";",
"        html += \"<div class=\\\"itemMeta\\\">Tracks Missing Subject: \" + escapeHtml2(String(health.tracks_missing_subject_count || 0)) + \"</div>\";",
"        html += \"<div class=\\\"itemMeta\\\">Tracks Missing Grade Level: \" + escapeHtml2(String(health.tracks_missing_grade_level_count || 0)) + \"</div>\";",
"        html += \"</div>\";",
"",
"        if (preview && preview.albums_missing_cover && preview.albums_missing_cover.length){",
