"  function studioRunUploadTrack(){",
"    var prefix = studioVal(\"studioUploadTrackPrefix\");",
"    var subject = studioVal(\"studioUploadSubject\");",
"    var biomoleculeClass = studioVal(\"studioUploadBiomoleculeClass\");",
"    var proteinType = studioVal(\"studioUploadProteinType\");",
"    var albumTitle = studioVal(\"studioUploadAlbumTitle\");",
"    if (!albumTitle) { studioSetResult(\"studioUploadResult\", \"Album title is required.\"); return; }",
"    if (!subject) { studioSetResult(\"studioUploadResult\", \"Subject is required.\"); return; }",
"    if (subject === \"BioMolecules\" && !biomoleculeClass) { studioSetResult(\"studioUploadResult\", \"Biomolecule Class is required.\"); return; }",
"    if (subject === \"BioMolecules\" && biomoleculeClass === \"Protein\" && !proteinType) { studioSetResult(\"studioUploadResult\", \"Protein Type is required.\"); return; }",
"    var fileInput = $(\"studioUploadTrackFile\");",
"    var files = fileInput && fileInput.files ? Array.prototype.slice.call(fileInput.files) : [];",
"    if (!files.length) { studioSetResult(\"studioUploadResult\", \"Please choose one or more track files.\"); return; }",
"",
"    studioSetResult(\"studioUploadResult\", \"Preparing batch upload for \" + files.length + \" track(s)...\");",
"",
"    var results = [];",
"    var idx = 0;",
"",
"    function runNext(){",
"      if (idx >= files.length){",
"        studioSetResult(\"studioUploadResult\", results.join(\"\\n\\n\"));",
"        return;",
"      }",
"",
"      var file = files[idx];",
"      var currentNum = idx + 1;",
"      studioSetResult(\"studioUploadResult\", \"Uploading track \" + currentNum + \" of \" + files.length + \": \" + file.name);",
"",
"      var fd = new FormData();",
"      fd.append(\"file\", file);",
"      if (prefix) fd.append(\"prefix\", prefix);",
"      fd.append(\"subject\", subject);",
"      if (biomoleculeClass) fd.append(\"biomolecule_class\", biomoleculeClass);",
"      if (proteinType) fd.append(\"protein_type\", proteinType);",
"      fd.append(\"album_title\", albumTitle);",
"      var genre = studioVal(\"studioUploadGenre\");",
"      if (genre) fd.append(\"genre\", genre);",
"      fd.append(\"filename\", file.name);",
"",
"      api(\"/api/admin/upload-track\", { method:\"POST\", body: fd })",
"        .then(function(out){",
"          var msg = \"✅ \" + file.name;",
"          try {",
"            if (out && out.album && out.album.path) msg += \" → \" + out.album.path;",
"            else if (out && out.key) msg += \" → \" + out.key;",
"            else if (out && out.message) msg += \" → \" + out.message;",
"          } catch(e){}",
"          results.push(msg);",
"          idx++;",
"          runNext();",
"        })",
"        .catch(function(e){",
"          results.push(\"❌ \" + file.name + \" → \" + e.message);",
"          idx++;",
"          runNext();",
"        });",
"    }",
"",
"    runNext();",
"  }",
"",
"  function studioRunUploadCover(){",
"    studioSetResult(\"studioUploadResult\", \"Uploading cover...\");",
"    var prefix = studioVal(\"studioUploadCoverPrefix\") || studioVal(\"studioUploadTrackPrefix\");",
"    var subject = studioVal(\"studioUploadSubject\");",
"    var biomoleculeClass = studioVal(\"studioUploadBiomoleculeClass\");",
"    var proteinType = studioVal(\"studioUploadProteinType\");",
"    var albumTitle = studioVal(\"studioUploadAlbumTitle\");",
"    if (!albumTitle) { studioSetResult(\"studioUploadResult\", \"Album title is required.\"); return; }",
