"    if (subject === \"BioMolecules\" && !biomoleculeClass) { studioSetResult(\"studioUploadResult\", \"Biomolecule Class is required.\"); return; }",
"    if (subject === \"BioMolecules\" && biomoleculeClass === \"Protein\" && !proteinType) { studioSetResult(\"studioUploadResult\", \"Protein Type is required.\"); return; }",
"    var fileInput = $(\"studioUploadCoverFile\");",
"    var file = fileInput && fileInput.files ? fileInput.files[0] : null;",
"    if (!file) { studioSetResult(\"studioUploadResult\", \"Please choose a cover image.\"); return; }",
"    var fd = new FormData();",
"    fd.append(\"file\", file);",
"    if (prefix) fd.append(\"prefix\", prefix);",
"    fd.append(\"subject\", subject);",
"    if (biomoleculeClass) fd.append(\"biomolecule_class\", biomoleculeClass);",
"    if (proteinType) fd.append(\"protein_type\", proteinType);",
"    fd.append(\"album_title\", albumTitle);",
"    var genre = studioVal(\"studioUploadGenre\");",
"    if (genre) fd.append(\"genre\", genre);",
"    fd.append(\"filename\", file.name);",
"    api(\"/api/admin/upload-cover\", { method:\"POST\", body: fd })",
"      .then(function(out){ studioSetResult(\"studioUploadResult\", out); })",
"      .catch(function(e){ studioSetResult(\"studioUploadResult\", \"Error: \" + e.message); });",
"  }",

"  function studioRunRaw(){",
"    studioSetResult(\"studioRawResult\", \"Running raw endpoint...\");",
"    var endpoint = studioVal(\"studioRawEndpoint\");",
