"            +       \"<div class=\\\"itemMeta\\\">Subject: \" + escapeHtml2(a.subject || \"-\") + ((String(a.subject || \"\") === \"Entertainment\") ? \"\" : (\" • Grade: \" + escapeHtml2(a.grade_level || \"-\"))) + \"</div>\"",
"            +       \"<div class=\\\"itemMeta\\\">Status: Pending Review</div>\"",
"            +       \"<div class=\\\"itemMeta\\\">Album ID: <code style=\\\"display:block;white-space:nowrap;overflow:auto;padding-top:4px\\\">\" + escapeHtml2(a.id || \"\") + \"</code></div>\"",
"            +     \"</div>\"",
"            +     \"<div class=\\\"itemBtns\\\">\"",
"            +       \"<button class=\\\"pill\\\" data-open-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Open Album</button>\"",
"            +       \"<button class=\\\"pill gold\\\" data-publish-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Publish Album</button>\"",
"            +       \"<button class=\\\"pill\\\" data-archive-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Archive Album</button>\"",
