"  function studioRunMyAlbums(){",
"    studioSetResult(\"studioMineResult\", \"Loading albums...\");",
"    var q = studioVal(\"studioLibrarySearch\");",
"    var subject = studioLibrarySubject();",
"    var status = studioLibraryStatus();",
"    var artist = $(\"studioLibraryArtist\") ? studioLibraryArtist() : \"\";",
"    var url = \"/api/my/albums?q=\" + encodeURIComponent(q);",
"    var isAdmin = !!(me && me.role && String(me.role).toLowerCase() === \"admin\");",
"    if (subject) url += \"&subject=\" + encodeURIComponent(subject);",
"    if (status) url += \"&status=\" + encodeURIComponent(status);",
"    if (artist) url += \"&artist=\" + encodeURIComponent(artist);",
"    api(url)",
"      .then(function(out){",
"        var host = $(\"studioMineResult\");",
"        if (!host) return;",
"",
"        if(!out || !out.albums){",
"          studioSetResult(\"studioMineResult\",\"No albums found.\");",
"          return;",
"        }",
"",
"        if(!out.albums.length){",
"          studioSetResult(\"studioMineResult\",\"No albums found.\");",
"          return;",
"        }",
"",
"        var html = \"\";",
