"            + \"<div class=\\\"item\\\" style=\\\"margin-bottom:10px\\\">\"",
"            +   \"<div class=\\\"itemTop\\\">\"",
"            +     \"<div style=\\\"min-width:0\\\">\"",
"            +       \"<div class=\\\"itemTitle\\\">\" + escapeHtml2(a.title || \"Untitled\") + \"</div>\"",
"            +       \"<div class=\\\"itemMeta\\\">Album ID: <code style=\\\"display:block;white-space:nowrap;overflow:auto;padding-top:4px\\\">\" + escapeHtml2(a.id || \"\") + \"</code></div>\"",
"            +       \"<div class=\\\"itemMeta\\\">Artist: \" + escapeHtml2(a.artist || \"-\") + \" • Subject: \" + escapeHtml2(a.subject || \"-\") + ((String(a.subject || \"\") === \"Entertainment\") ? \"\" : (\" • Grade: \" + escapeHtml2(a.grade_level || \"-\"))) + \" • Status: \" + escapeHtml2((String(a.status || \"\").toLowerCase() === \"draft\") ? \"Draft (Not submitted)\" : ((String(a.status || \"\").toLowerCase() === \"pending_review\") ? \"Pending Review\" : ((String(a.status || \"\").toLowerCase() === \"published\") ? \"Published\" : (a.status || \"-\")))) + \"</div>\"",
"            +     \"</div>\"",
"            +     \"<div class=\\\"itemBtns\\\">\"",
"            +       \"<button class=\\\"pill\\\" data-copy-album-id=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Copy Album ID</button>\"",
"            +       \"<button class=\\\"pill\\\" data-open-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Open Album</button>\"",
"            +       ((!isAdmin && String(a.status || \"\").toLowerCase() === \"draft\") ? \"<button class=\\\"pill gold\\\" data-submit-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Submit for Review</button>\" : \"\")",
"            +       ((!isAdmin && String(a.status || \"\").toLowerCase() === \"draft\" && Number(a.track_count || 0) === 0) ? \"<button class=\\\"pill danger\\\" data-delete-draft-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Delete Draft</button>\" : \"\")",
"            +       (isAdmin ? \"<button class=\\\"pill gold\\\" data-audit-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Audit Album</button>\" : \"\")",
"            +       (isAdmin ? \"<button class=\\\"pill\\\" data-rebuild-cover=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Rebuild Cover</button>\" : \"\")",
"            +       (isAdmin ? \"<button class=\\\"pill\\\" data-relink-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Relink Tracks</button>\" : \"\")",
"            +       (isAdmin ? \"<button class=\\\"pill\\\" data-fill-album-meta=\\\"\" + albumPayload + \"\\\">Load Meta</button>\" : \"\")",
"            +       (isAdmin ? ((String(a.status || \"\").toLowerCase() === \"archived\") ? (\"<button class=\\\"pill gold\\\" data-unarchive-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Unarchive Album</button>\") : ((String(a.status || \"\").toLowerCase() === \"published\") ? (\"<button class=\\\"pill gold\\\" data-archive-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Archive Album</button>\") : (\"<button class=\\\"pill gold\\\" data-publish-album=\\\"\" + escapeHtml2(a.id || \"\") + \"\\\">Publish Album</button>\"))) : \"\")",
"            +     \"</div>\"",
"            +   \"</div>\"",
"            + \"</div>\";",
"        }",
"",
"        host.innerHTML = html;",
"        studioBindMyLibraryAlbumButtons(host);",
