"      var proteinWrap = $(\"studioProteinTypeWrap\");",
"      var classWrap = $(\"studioBiomoleculeClassWrap\");",
"      if (classWrap) classWrap.style.display = (val === \"BioMolecules\") ? \"\" : \"none\";",
"      if (proteinWrap) proteinWrap.style.display = \"none\";",
"    };",
"    if ($(\"studioUploadBiomoleculeClass\")) $(\"studioUploadBiomoleculeClass\").onchange = function(){",
"      var proteinWrap = $(\"studioProteinTypeWrap\");",
"      if (proteinWrap) proteinWrap.style.display = (String(this.value || \"\") === \"Protein\") ? \"\" : \"none\";",
"    };",
"",
"    if ($(\"studioLibrarySubject\")) $(\"studioLibrarySubject\").onchange = function(){",
"      if (window.__ssStudioLibraryMode === \"tracks\"){",
"        studioRunMyTracks();",
"        return;",
"      }",
"      window.__ssStudioLibraryMode = \"albums\";",
"      studioRunMyAlbums();",
"    };",
"",
"    if ($(\"studioLibraryStatus\")) $(\"studioLibraryStatus\").onchange = function(){",
"      if (window.__ssStudioLibraryMode === \"tracks\"){",
"        studioRunMyTracks();",
"        return;",
"      }",
"      window.__ssStudioLibraryMode = \"albums\";",
"      studioRunMyAlbums();",
"    };",
"",
"    if ($(\"studioLibraryArtist\")) $(\"studioLibraryArtist\").onkeydown = function(e){",
"      if (!e) return;",
"      if (e.key !== \"Enter\") return;",
"      e.preventDefault();",
"      if (window.__ssStudioLibraryMode === \"tracks\"){",
"        studioRunMyTracks();",
"        return;",
"      }",
"      window.__ssStudioLibraryMode = \"albums\";",
"      studioRunMyAlbums();",
"    };",
"  }",

"",
"  function renderMobileMiniPlayer(){",
"    var box = $(\"mobileMiniPlayer\");",
"    if (!box) return;",
"    var now = getNowPlaying();",
"    if (!now){",
"      box.innerHTML = '<div class=\"mmpRow\"><button class=\"mmpBtn\" disabled>▶</button><div style=\"min-width:0;flex:1\"><div class=\"mmpTitle\">Nothing playing</div><div class=\"mmpMeta\">Pick a track to start listening</div></div></div><div class=\"mmpBar\"><div class=\"mmpFill\" style=\"width:0%\"></div></div>';",
"      return;",
"    }",
"    box.innerHTML = ''",
"      + '<div class=\"mmpRow\">'",
"      +   '<button class=\"mmpBtn\" id=\"mmpPlayPause\">' + ((player && !player.paused) ? '⏸ Pause' : '▶ Play') + '</button>'",
"      +   '<button class=\"mmpBtn\" id=\"mmpNext\">⏭ Next</button>'",
"      +   '<div style=\"min-width:0;flex:1\">'",
"      +     '<div class=\"mmpTitle\">' + escapeHtml2(prettyTitle(now.title || now.id || 'Untitled')) + '</div>'",
"      +     '<div class=\"mmpMeta\">' + escapeHtml2((now.artist || 'SaySay') + (now.subject ? (' • ' + now.subject) : '')) + '</div>'",
"      +   '</div>'",
"      + '</div>'",
"      + '<div class=\"mmpBar\"><div class=\"mmpFill\" id=\"mmpFill\"></div></div>';",
"    var pp = $(\"mmpPlayPause\");",
"    if (pp) pp.onclick = function(){",
"      if (!player || !player.src){ toast(\"Nothing playing\"); return; }",
"      if (player.paused) player.play().catch(function(){}); else player.pause();",
"      setTimeout(renderMobileMiniPlayer, 80);",
"    };",
"    var nx = $(\"mmpNext\");",
"    if (nx) nx.onclick = function(){ nextTrack(); setTimeout(renderMobileMiniPlayer, 80); };",
"    var fill = $(\"mmpFill\");",
"    if (fill && player && player.duration){",
"      var pct = Math.max(0, Math.min(100, ((player.currentTime || 0) / player.duration) * 100));",
"      fill.style.width = pct + '%';",
"    }",
"  }",
"",
"  function renderBottomMiniPlayer(){",
"    var box = $(\"bottomMiniPlayer\");",
"    if (!box) return;",
