"    }",
"",
"    var now = getNowPlaying();",
"",
"    if (!now){",
"      box.style.display = \"block\";",
"      box.innerHTML = '<div class=\"miniHelp\" style=\"margin-bottom:8px\">' + ((me && String((me.plan||\"\")).toLowerCase() === \"free\") ? ('Free plan: ' + getRemainingFreeMinutes(me) + ' minutes left today.') : 'Ready to play') + '</div>' + ''",
"        + '<div class=\"bmpRow\" style=\"min-height:52px\">'",
"        +   '<div class=\"bmpMeta\">'",
"        +     '<div class=\"bmpTitle\">Ready to play</div>'",
"        + '<div class=\"bmpSub\">' + (((me && String((me.plan||\"\")).toLowerCase() === \"free\") ? ('Free plan: ' + getRemainingFreeMinutes(me) + ' minutes left today.') : 'Browse Home, Subject, or All and tap Play')) + '</div>'",
"        +   '</div>'",
"        +   '<button class=\"bmpBtn\" id=\"bmpHomeBtn\">🏠</button>'",
"        +   '<button class=\"bmpBtn\" id=\"bmpSubjectBtn\">🧭</button>'",
"        +   '<button class=\"bmpBtn\" id=\"bmpAllBtn\">📚</button>'",
"        +   '<button class=\"bmpBtn\" id=\"bmpPlayPause\" style=\"min-width:44px;min-height:44px;font-size:16px;padding:10px 12px\" disabled>▶</button>'",
"        + '</div>'",
"        + '<div class=\"bmpBar\"><div class=\"bmpFill\" style=\"width:0%\"></div></div>';",
"",
"      var homeBtnEmpty = $(\"bmpHomeBtn\");",
