"  function getStreamUrl(track){",
"    if (!track || !track.id) return \"\";",
"    if (track.stream_url && track.stream_url.indexOf(\"/api/\") === 0) return API + track.stream_url;",
"    if (track.stream_url) return track.stream_url;",
"    return API + \"/api/stream/\" + encodeURIComponent(track.id);",
"  }",
"",
"  function getShareLink(track){",
"    if (!track || !track.id) return \"https://app.saysaymusic.com/\";",
"    var parts = [];",
"    parts.push(\"track=\" + encodeURIComponent(track.id));",
"    if (track.title) parts.push(\"title=\" + encodeURIComponent(track.title));",
"    if (track.artist) parts.push(\"artist=\" + encodeURIComponent(track.artist));",
"    if (track.subject) parts.push(\"subject=\" + encodeURIComponent(track.subject));",
"    return \"https://app.saysaymusic.com/?\" + parts.join(\"&\");",
"  }",
