"  function addUpNext(track){",
"    if (!track || !track.id) return;",
"    if (queueIndex < 0){ queue = [track]; queueIndex = 0; renderQueueCount(); return toast(\"Added to queue ✅\"); }",
"    queue.splice(queueIndex + 1, 0, track);",
"    renderQueueCount();",
"    toast(\"Up next ✅\");",
"  }",

"  function playTrack(track, opts){",
"    opts = opts || {};",
"    if (!track || !track.id) return;",
"    if (playPending){ toast(\"Loading track...\"); return; }",
"    if (!opts.fromQueue){",
"      if (opts.enqueue){",
"        if (queueIndex < 0){ queue = [track]; queueIndex = 0; }",
"        else { queue.splice(queueIndex + 1, 0, track); queueIndex++; }",
"      } else {",
"        queue = [track];",
"        queueIndex = 0;",
"      }",
"      renderQueueCount();",
"    }",
"    guestPreviewLocked = false;",
"    window.__ssLastUsageTickAt = 0;",
"    playPending = true;",
"    setNowPlayingUI(track);",
"    renderMobileMiniPlayer();",
"    renderBottomMiniPlayer();",
"    try { player.pause(); } catch(e){}",
"    resetDailyUsageIfNeeded();",
"    var accessMode = getPlaybackAccessMode(me);",
"    if (accessMode === \"free_blocked\"){",
"      toast(\"Daily Free limit reached. Tap Upgrade for Premium or Artist access.\");",
"      return;",
"    }",
"    player.src = getStreamUrl(track);",
"    player.load();",
"",
"    function clearPending(){",
"      playPending = false;",
"      renderMobileMiniPlayer();",
"      renderBottomMiniPlayer();",
"    }",
"",
"    function onPlaying(){",
"      player.removeEventListener(\"playing\", onPlaying);",
"      player.removeEventListener(\"canplay\", onCanPlay);",
"      player.removeEventListener(\"error\", onError);",
"      clearPending();",
"    }",
"",
"    function onCanPlay(){",
"      player.removeEventListener(\"playing\", onPlaying);",
"      player.removeEventListener(\"canplay\", onCanPlay);",
"      player.removeEventListener(\"error\", onError);",
"      clearPending();",
"    }",
"",
"    function onError(){",
"      player.removeEventListener(\"playing\", onPlaying);",
"      player.removeEventListener(\"canplay\", onCanPlay);",
"      player.removeEventListener(\"error\", onError);",
"      playPending = false;",
"      toast(\"Track failed to load\");",
"      renderMobileMiniPlayer();",
"      renderBottomMiniPlayer();",
"    }",
"",
"    player.addEventListener(\"playing\", onPlaying);",
"    player.addEventListener(\"canplay\", onCanPlay);",
"    player.addEventListener(\"error\", onError);",
"    renderMobileMiniPlayer();",
"    player.play().catch(function(){",
"      playPending = false;",
"      renderMobileMiniPlayer();",
"      renderBottomMiniPlayer();",
"    });",
"    renderBottomMiniPlayer();",
"    logPlay(track);",
"    if (me) saveNowPlaying();",
"    addContinue(track, 0);",
"  }",
"",
"  function playFromVisibleList(track){",
"    if (!track || !track.id) return;",
"    var list = LAST_LIST || [];",
"    if (!list.length){",
"      queue = [track]; queueIndex = 0; renderQueueCount();",
"      playTrack(track, { fromQueue:true });",
"      return;",
"    }",
"    var idx = -1;",
"    for (var i=0;i<list.length;i++){ if (list[i] && list[i].id === track.id){ idx = i; break; } }",
"    if (idx < 0) idx = 0;",
"    queue = list.slice(0);",
"    queueIndex = idx;",
"    renderQueueCount();",
"    playTrack(queue[queueIndex], { fromQueue:true });",
"  }",
"",
"  function findNextAlbumForAutoAdvance(){",
