"    if (current.subject) list = getAlbumsBySubject(current.subject);",
"    if (!list.length) list = HOME_ALBUMS.slice(0);",
"    var idx = -1;",
"    for (var i=0;i<list.length;i++){ if (list[i] && list[i].id === current.id){ idx = i; break; } }",
"    if (idx < 0) return null;",
"    if (idx + 1 < list.length) return list[idx + 1];",
"    return null;",
"  }",
"",
"  function nextTrack(){",
"    if (!queue.length) return;",
"    if (repeat === \"one\"){ player.currentTime = 0; player.play().catch(function(){}); return; }",
"    if (shuffle){ queueIndex = Math.floor(Math.random() * queue.length); }",
"    else {",
"      queueIndex++;",
"      if (queueIndex >= queue.length){",
"        if (repeat === \"all\") queueIndex = 0;",
"        else {",
"          var nextAlbum = window.__ssAutoAdvance ? findNextAlbumForAutoAdvance() : null;",
