"            return;",
"          }",
"          queueIndex = queue.length - 1;",
"          return;",
"        }",
"      }",
"    }",
"    playTrack(queue[queueIndex], { fromQueue:true });",
"  }",
"",
"  function prevTrack(){",
"    if (!queue.length) return;",
