"  function detectMathSearch(raw){",
"    var txt = String(raw || \"\").toLowerCase();",
"    var compact = txt.replace(/[^a-z0-9]/g, \"\");",
"",
"    var map = [",
"      {key:\"ElementaryGrade3\", grade:\"3\"},",
"      {key:\"ElementaryGrade4\", grade:\"4\"},",
"      {key:\"ElementaryGrade5\", grade:\"5\"},",
"      {key:\"Grade_6\", grade:\"6\"},",
"      {key:\"MiddleMathGrade7\", grade:\"7\"},",
"      {key:\"MiddleMathGrade8\", grade:\"8\"},",
"      {key:\"HighSMathGrade9\", grade:\"9\"},",
"      {key:\"HighSMathGrade10\", grade:\"10\"},",
"      {key:\"HighSMathGrade11\", grade:\"11\"},",
"      {key:\"HighSMathGrade12\", grade:\"12\"}",
"    ];",
"",
"    for (var i=0;i<map.length;i++){",
"      var lookup = String(map[i].key || \"\").toLowerCase().replace(/[^a-z0-9]/g, \"\");",
"      if (compact.indexOf(lookup) !== -1){",
"        return { subject:\"Math\", grade:map[i].grade, quick:map[i].key };",
"      }",
"    }",
"",
"    if (/algebra\\s*1/.test(txt) || compact.indexOf(\"algebra1\") !== -1) return { subject:\"Math\", grade:\"\", quick:\"Algebra1\" };",
"    if (/algebra\\s*2/.test(txt) || compact.indexOf(\"algebra2\") !== -1) return { subject:\"Math\", grade:\"\", quick:\"Algebra2\" };",
"    if (/algebra\\s*3/.test(txt) || compact.indexOf(\"algebra3\") !== -1) return { subject:\"Math\", grade:\"\", quick:\"Algebra3\" };",
"",
"    if ((txt.indexOf(\"math\") !== -1) || /grade\\s*\\d+/.test(txt)){",
"      if (/grade\\s*3/.test(txt)) return { subject:\"Math\", grade:\"3\", quick:\"ElementaryGrade3\" };",
"      if (/grade\\s*4/.test(txt)) return { subject:\"Math\", grade:\"4\", quick:\"ElementaryGrade4\" };",
"      if (/grade\\s*5/.test(txt)) return { subject:\"Math\", grade:\"5\", quick:\"ElementaryGrade5\" };",
"      if (/grade\\s*6/.test(txt)) return { subject:\"Math\", grade:\"6\", quick:\"Grade_6\" };",
"      if (/grade\\s*7/.test(txt)) return { subject:\"Math\", grade:\"7\", quick:\"MiddleMathGrade7\" };",
"      if (/grade\\s*8/.test(txt)) return { subject:\"Math\", grade:\"8\", quick:\"MiddleMathGrade8\" };",
"      if (/grade\\s*9/.test(txt)) return { subject:\"Math\", grade:\"9\", quick:\"HighSMathGrade9\" };",
"      if (/grade\\s*10/.test(txt)) return { subject:\"Math\", grade:\"10\", quick:\"HighSMathGrade10\" };",
"      if (/grade\\s*11/.test(txt)) return { subject:\"Math\", grade:\"11\", quick:\"HighSMathGrade11\" };",
"      if (/grade\\s*12/.test(txt)) return { subject:\"Math\", grade:\"12\", quick:\"HighSMathGrade12\" };",
"      return { subject:\"Math\", grade:\"\", quick:\"\" };",
"    }",
"",
"    return null;",
"  }",
