"  function computeSubjectStats(subject, albums, tracks){",
"    var artistSet = {};",
"    var gradeSet = {};",
"    var groupSet = {};",
"    var low = null;",
"    var high = null;",
"    for (var i=0;i<(albums||[]).length;i++){",
"      var a = albums[i] || {};",
"      if (a.artist) artistSet[String(a.artist)] = true;",
"      if (a.grade_level){",
"        gradeSet[String(a.grade_level)] = true;",
"        var n = parseInt(String(a.grade_level), 10);",
"        if (isFinite(n)){",
"          if (low === null || n < low) low = n;",
"          if (high === null || n > high) high = n;",
"        }",
"      }",
"      if (a.grade_group) groupSet[String(a.grade_group)] = true;",
"    }",
"    for (var j=0;j<(tracks||[]).length;j++){",
"      var t = tracks[j] || {};",
"      if (t.artist) artistSet[String(t.artist)] = true;",
"    }",
"    return {",
"      albums: (albums || []).length,",
"      tracks: (tracks || []).length,",
"      artists: Object.keys(artistSet).length,",
"      grades: Object.keys(gradeSet).length,",
"      groups: Object.keys(groupSet).length,",
"      gradeRange: (low !== null && high !== null) ? ((low === high) ? (\"Grade \" + low) : (\"Grades \" + low + \"–\" + high)) : (Object.keys(groupSet).length ? Object.keys(groupSet).join(\", \") : \"Multi-level\")",
"    };",
"  }",
