"",
"  function renderSubjectAlbumLibrary(subject, albums){",
"    setActiveNavButton(\"btnSubject\");",
"    mode = \"subject\";",
"    window.__ssOpenSubject = subject || null;",
"    window.__ssOpenArtist = null;",
"    window.__ssOpenAlbum = null;",
"    window.__ssOpenAlbumTracks = [];",
"    window.__ssOpenSubjectTracks = [];",
"    window.__ssNavSource = { type:\"subject\", value:subject || null };",
"    setModeChips();",
"    setCrumbs();",
"    renderFilterBar(\"albums\", albums || []);",
"",
"    var list = $(\"list\");",
"    list.innerHTML = \"\";",
"    LAST_LIST = [];",
"    $(\"homeWrap\").style.display = \"none\";",
"",
"    var head = document.createElement(\"div\");",
"    head.className = \"subjectSectionHead\";",
"    head.innerHTML = '<div class=\"shelfTitle\">' + escapeHtml2(subject || \"Subject\") + ' Albums</div><div class=\"muted\">Album library view</div>';",
"    list.appendChild(head);",
"",
"    if (albums && albums.length){",
"      var row = document.createElement(\"div\");",
"      row.className = \"shelfRow\";",
"      row.style.flexWrap = \"wrap\";",
"      row.style.overflow = \"visible\";",
"      for (var i=0;i<albums.length;i++){ row.appendChild(makeAlbumCard(albums[i] || {})); }",
"      list.appendChild(row);",
"    } else {",
"      var empty = document.createElement(\"div\");",
"      empty.className = \"subjectEmpty\";",
"      empty.textContent = \"No albums found for this subject.\";",
"      list.appendChild(empty);",
"    }",
"",
"    $(\"footNote\").textContent = \"Browsing albums for \" + (subject || \"Subject\") + \".\";",
"  }",

"  function renderGlobalResults(filteredAlbums, filteredTracks){",
"    var list = $(\"list\");",
"    list.innerHTML = \"\";",
"    LAST_LIST = [];",
"    var aHead = document.createElement(\"div\");",
"    aHead.className = \"shelfTitle\";",
"    aHead.textContent = \"Albums\";",
"    list.appendChild(aHead);",
"    var aRow = document.createElement(\"div\");",
"    aRow.className = \"shelfRow\";",
"    aRow.style.flexWrap = \"wrap\";",
"    aRow.style.overflow = \"visible\";",
"    for (var i=0;i<(filteredAlbums||[]).length;i++){ aRow.appendChild(makeAlbumCard(filteredAlbums[i] || {})); }",
"    list.appendChild(aRow);",
"    var div = document.createElement(\"div\");",
"    div.className = \"sectionDivider\";",
"    list.appendChild(div);",
"    var tHead = document.createElement(\"div\");",
"    tHead.className = \"shelfTitle\";",
"    tHead.textContent = \"Tracks\";",
"    list.appendChild(tHead);",
"    LAST_LIST = [];",
"    for (var j=0;j<(filteredTracks||[]).length;j++){",
"      list.appendChild(buildTrackRow(normTrack(filteredTracks[j] || {}), false));",
"      LAST_LIST.push(normTrack(filteredTracks[j] || {}));",
"    }",
"  }",

"  function rerunCurrentMode(){",
"    if ($(\"search\")) VIEW.q = String($(\"search\").value || \"\").trim();",
"    if (mode === \"home\") return loadHome();",
"    if (mode === \"trending\") return loadTrending();",
"    if (mode === \"all\") return loadAll();",
"    if (mode === \"global\") return loadGlobal();",
"    if (mode === \"subject\" && window.__ssOpenSubject) return showSubjectAll(window.__ssOpenSubject);",
"    if (mode === \"subject\" && !window.__ssOpenSubject) return showSubjectBrowser();",
"    if (mode === \"artist\" && window.__ssOpenArtist) return showArtistAll(window.__ssOpenArtist);",
"    if (mode === \"album\" && window.__ssOpenAlbum) return openAlbum(window.__ssOpenAlbum, { navSourceType:(window.__ssNavSource ? window.__ssNavSource.type : null), navSourceValue:(window.__ssNavSource ? window.__ssNavSource.value : null) });",
"    if (mode === \"studio\") return loadStudio();",
"    return loadHome();",
"  }",

"  function loadLikes(){",
"    var box = $(\"libList\");",
"    if (!me){ box.innerHTML = '<div class=\"muted\">Login to see your Likes ❤️</div>'; return; }",
"    box.innerHTML = '<div class=\"muted\">Loading likes…</div>';",
"    api(\"/api/my/likes\").then(function(out){",
"      var items = (out && out.tracks) ? out.tracks : [];",
"      box.innerHTML = \"\";",
"      if (!items.length){ box.innerHTML = '<div class=\"muted\">No likes yet. Tap ❤️ Like on a track.</div>'; return; }",
"      for (var i=0;i<items.length;i++){ box.appendChild(buildTrackRow(normTrack(items[i]||{}), true)); }",
"    }).catch(function(e){",
"      box.innerHTML = '<div class=\"muted\">Likes load failed: ' + escapeHtml2(e.message) + '</div>';",
"    });",
"  }",

"  function renderContinue(){",
"    var items = getContinue();",
"    var box = $(\"libList\");",
"    box.innerHTML = \"\";",
"    if (!items.length){ box.innerHTML = '<div class=\"muted\">Nothing yet. Play a track and it will show here.</div>'; return; }",
"    for (var i=0;i<Math.min(20, items.length);i++){",
"      var it = items[i] || {};",
"      var t = { id: it.id, title: it.title, artist: it.artist, stream_url: it.stream_url };",
"      box.appendChild(buildTrackRow(normTrack(t), true));",
"    }",
"  }",

"  function setLibTab(name){",
"    document.querySelectorAll(\"[data-lib]\").forEach(function(el){",
"      el.classList.toggle(\"active\", el.getAttribute(\"data-lib\") === name);",
"    });",
"    if (name === \"continue\") renderContinue();",
"    if (name === \"likes\") loadLikes();",
"  }",

"  function openAlbum(alb, opts){",
"    setActiveNavButton(null);",
"    opts = opts || {};",
"    mode = \"album\";",
"    window.__ssOpenAlbum = alb || null;",
"    window.__ssOpenAlbumTracks = [];",
"    if (alb && alb.subject) window.__ssOpenSubject = alb.subject;",
"    if (opts.navSourceType){ window.__ssNavSource = { type:opts.navSourceType, value:(opts.navSourceValue || null) }; }",
"    else if (alb && alb.subject){ window.__ssNavSource = { type:\"subject\", value:alb.subject }; }",
"    else if (alb && alb.artist){ window.__ssNavSource = { type:\"artist\", value:alb.artist }; }",
"    setModeChips(); setCrumbs();",
"    $(\"filterWrap\").innerHTML = \"\";",
"    $(\"homeWrap\").style.display = \"none\";",
"    $(\"footNote\").textContent = \"Album: \" + (alb && alb.title ? alb.title : \"\");",
"    var albId = alb && alb.id ? alb.id : \"\";",
