"          for (var k=0;k<tracks.length;k++){",
"            var tr = tracks[k] || {};",
"            var s = ((tr.title||\"\") + \" \" + (tr.artist||\"\") + \" \" + (tr.id||\"\")).toLowerCase();",
"            if (s.indexOf(q) !== -1) f.push(tr);",
