"        var hdr = loadingHdr;",
"        hdr.className = \"item\";",
"        hdr.style.marginBottom = \"12px\";",
"        hdr.innerHTML = '<div style=\"display:flex;gap:14px;align-items:center\">' +",
"          '<img src=\"' + escapeHtml2(safeCoverUrl(alb)) + '\" style=\"width:110px;height:110px;border-radius:14px;object-fit:cover;border:1px solid rgba(255,191,0,.18)\"/>' +",
"          '<div><div class=\"itemTitle\" style=\"font-size:20px\">' + escapeHtml2(prettyTitle(alb && alb.title ? alb.title : \"Album\")) + '</div>' +",
"          '<div class=\"itemMeta\"><span class=\"artistLink\" id=\"albumArtistLink\">' + escapeHtml2(alb && alb.artist ? alb.artist : \"SaySay\") + '</span></div><div class=\"controls\" style=\"margin-top:10px\"><button class=\"btn primary\" id=\"albumPlayBtn\">▶️ Play Album</button><button class=\"btn\" id=\"albumQueueBtn\">➕ Queue Album</button><button class=\"btn\" id=\"albumArtistBtn\">👤 Artist</button><button class=\"btn\" id=\"albumCopyLinkBtn\">🔗 Album Link</button></div></div></div>';",
"        $(\"list\").prepend(hdr);",
