"  function showSubjectAll(subject){",
"    setActiveNavButton(\"btnSubject\");",
"    mode = \"subject\";",
"    window.__ssOpenSubject = subject || null;",
"    window.__ssOpenArtist = null;",
"    window.__ssOpenAlbum = null;",
"    window.__ssOpenAlbumTracks = [];",
"    window.__ssOpenSubjectTracks = [];",
"    window.__ssNavSource = { type:\"subject\", value:subject || null };",
"    window.__ssSubjectQuickJump = \"\";",
"    setModeChips(); setCrumbs();",
"    $(\"homeWrap\").style.display = \"none\";",

"    var qAlbums = buildQuery({",
"      limit: ALBUM_LIMIT,",
"      q: VIEW.q || \"\",",
"      subject: subject || \"\",",
"      grade_level: VIEW.grade_level || \"\",",
"      grade_group: VIEW.grade_group || \"\",",
"      sort: VIEW.sort === \"popularity\" ? \"newest\" : (VIEW.sort || \"newest\")",
"    });",

"    var qTracks = buildQuery({",
"      limit: TRACK_LIMIT,",
"      q: VIEW.q || \"\",",
"      subject: subject || \"\",",
"      grade_level: VIEW.grade_level || \"\",",
"      grade_group: VIEW.grade_group || \"\",",
"      sort: VIEW.sort || \"newest\"",
"    });",

"    Promise.all([api(\"/api/albums\" + qAlbums), api(\"/api/tracks\" + qTracks)]).then(function(arr){",
"      var albums = (arr[0] && arr[0].albums) ? arr[0].albums : [];",
"      var tracks = (arr[1] && arr[1].tracks) ? arr[1].tracks : [];",
"      window.__ssOpenSubjectTracks = tracks.slice(0);",
"      renderFilterBar(\"albums\", albums.concat(tracks));",
"      renderSubjectLanding(subject, albums, tracks);",
"      toast(\"Subject loaded ✅\");",
"    }).catch(function(e){",
"      renderFilterBar(\"albums\", []);",
"      $(\"list\").innerHTML = \"\";",
"      var fail = document.createElement(\"div\");",
"      fail.className = \"subjectEmpty\";",
"      fail.textContent = \"Subject load failed: \" + e.message;",
"      $(\"list\").appendChild(fail);",
"      $(\"footNote\").textContent = \"Subject failed to load.\";",
"    });",
"  }",

"  function showArtistAll(artist){",
"    setActiveNavButton(null);",
"    mode = \"artist\";",
"    window.__ssOpenArtist = artist || \"SaySay\";",
"    window.__ssOpenAlbum = null;",
"    window.__ssOpenAlbumTracks = [];",
"    window.__ssOpenSubject = null;",
"    window.__ssOpenSubjectTracks = [];",
"    window.__ssNavSource = { type:\"artist\", value:artist || \"SaySay\" };",
"    setModeChips(); setCrumbs();",
"    $(\"homeWrap\").style.display = \"none\";",
"    var items = getAlbumsByArtist(artist || \"SaySay\");",
"    if (VIEW.q){",
"      var qq = String(VIEW.q || \"\").toLowerCase();",
"      items = items.filter(function(a){",
"        var s = ((a.title||\"\") + \" \" + (a.artist||\"\") + \" \" + (a.subject||\"\") + \" \" + (a.grade_level||\"\") + \" \" + (a.grade_group||\"\") + \" \" + (a.id||\"\")).toLowerCase();",
"        return s.indexOf(qq) !== -1;",
"      });",
"    }",
"    if (VIEW.subject) items = items.filter(function(a){ return String(a.subject || \"\") === String(VIEW.subject); });",
"    if (VIEW.grade_level) items = items.filter(function(a){ return String(a.grade_level || \"\") === String(VIEW.grade_level); });",
"    if (VIEW.grade_group) items = items.filter(function(a){ return String(a.grade_group || \"\") === String(VIEW.grade_group); });",
"    renderFilterBar(\"albums\", items);",
