"      '<div class=\"shelfRow\" id=\"bioMoleculesAlbums\" style=\"display:none\"></div>';",
"    wrap.appendChild(bioPanel);",
"    var bioClassSelect = bioPanel.querySelector(\"#bioMoleculeClass\");",
