"  function authResetMessages(){",
"    AUTH_UI.error = \"\";",
"    AUTH_UI.success = \"\";",
"  }",
"",
"  function authOpen(modeName){",
"    AUTH_UI.mode = modeName || \"login\";",
"    AUTH_UI.busy = false;",
"    authResetMessages();",
"    renderAuth();",
"    setTimeout(function(){",
"      var first = AUTH_UI.mode === \"signup\" ? $(\"authSignupHandle\") : $(\"authLoginHandle\");",
"      if (first) first.focus();",
"    }, 0);",
"  }",
"",
"  function authClose(){",
"    AUTH_UI.mode = \"\";",
"    AUTH_UI.busy = false;",
"    authResetMessages();",
"    renderAuth();",
"  }",
"",
"  function authSetError(msg){",
"    AUTH_UI.error = String(msg || \"Something went wrong\");",
"    AUTH_UI.success = \"\";",
"    AUTH_UI.busy = false;",
"    renderAuth();",
"  }",
"",
"  function authSetSuccess(msg){",
"    AUTH_UI.success = String(msg || \"Success\");",
"    AUTH_UI.error = \"\";",
"    AUTH_UI.busy = false;",
"    renderAuth();",
"  }",
"",
"  function authPanelStyle(){",
"    return [",
"      \"width:100%\",",
"      \"margin-top:10px\",",
"      \"padding:12px\",",
"      \"border:1px solid rgba(255,191,0,.18)\",",
"      \"border-radius:18px\",",
"      \"background:linear-gradient(180deg, rgba(255,191,0,.08), rgba(255,255,255,.03))\",",
"      \"box-shadow:var(--shadow)\"",
"    ].join(\";\");",
"  }",
"",
"  function authFieldWrapStyle(){",
"    return [",
"      \"display:flex\",",
"      \"flex-direction:column\",",
"      \"gap:6px\",",
"      \"min-width:220px\",",
"      \"flex:1 1 220px\"",
"    ].join(\";\");",
"  }",
"",
"  function authMsgStyle(kind){",
"    var base = [",
"      \"margin-top:10px\",",
"      \"padding:10px 12px\",",
"      \"border-radius:14px\",",
"      \"font-size:12px\",",
"      \"font-weight:800\"",
"    ];",
"    if (kind === \"error\"){",
"      base.push(\"border:1px solid rgba(255,80,80,.28)\");",
"      base.push(\"background:rgba(255,80,80,.10)\");",
"      base.push(\"color:#ffd1d1\");",
"    } else {",
"      base.push(\"border:1px solid rgba(100,255,160,.24)\");",
"      base.push(\"background:rgba(100,255,160,.08)\");",
"      base.push(\"color:#d8ffe6\");",
"    }",
"    return base.join(\";\");",
"  }",
"",
"  function bindAuthPanelEvents(){",
"    var loginSubmit = $(\"authLoginSubmit\");",
"    if (loginSubmit) {",
"      loginSubmit.onclick = function(){",
"        if (AUTH_UI.busy) return;",
"        var handle = String((( $(\"authLoginHandle\") && $(\"authLoginHandle\").value) || \"\")).trim();",
"        var password = String((( $(\"authLoginPassword\") && $(\"authLoginPassword\").value) || \"\"));",
"        if (!handle) return authSetError(\"Username is required.\");",
"        if (!password) return authSetError(\"Password is required.\");",
"        AUTH_UI.busy = true;",
"        authResetMessages();",
"        renderAuth();",
"        api(\"/api/auth/login\", {",
"          method: \"POST\",",
"          body: JSON.stringify({ handle: handle, password: password })",
"        }).then(function(out){",
"          me = out && out.user ? out.user : null;",
"          AUTH_UI.busy = false;",
"          AUTH_UI.mode = \"\";",
"          AUTH_UI.error = \"\";",
"          AUTH_UI.success = \"\";",
"          AUTH_UI.notice = \"\";",
"          AUTH_UI.noticeKind = \"success\";",
"          renderAuth();",
"          renderStatusChips();",
"          loadLikes();",
"          toast(\"Logged in ✅\");",
"          loadHome();",
"        }).catch(function(e){",
"          authSetError(\"Login failed: \" + e.message);",
"        });",
"      };",
"    }",
"",
"    var signupSubmit = $(\"authSignupSubmit\");",
"    if (signupSubmit) {",
"      signupSubmit.onclick = function(){",
"        if (AUTH_UI.busy) return;",
"        var handle = String((( $(\"authSignupHandle\") && $(\"authSignupHandle\").value) || \"\")).trim();",
"        var email = String((( $(\"authSignupEmail\") && $(\"authSignupEmail\").value) || \"\")).trim();",
"        var password = String((( $(\"authSignupPassword\") && $(\"authSignupPassword\").value) || \"\"));",
"        if (!handle) return authSetError(\"Username is required.\");",
"        if (!email) return authSetError(\"Email is required.\");",
"        if (!password) return authSetError(\"Password is required.\");",
"        if (password.length < 6) return authSetError(\"Password must be at least 6 characters.\");",
"        AUTH_UI.busy = true;",
"        authResetMessages();",
"        renderAuth();",
"        api(\"/api/auth/register\", {",
"          method: \"POST\",",
"          body: JSON.stringify({ handle: handle, email: email, password: password, plan: \"free\" })",
"        }).then(function(out){",
"          me = out && out.user ? out.user : null;",
"          AUTH_UI.busy = false;",
"          AUTH_UI.mode = \"\";",
"          AUTH_UI.error = \"\";",
"          AUTH_UI.success = \"\";",
"          AUTH_UI.notice = \"\";",
"          AUTH_UI.noticeKind = \"success\";",
"          renderAuth();",
"          renderStatusChips();",
"          loadLikes();",
"          toast(\"Account created ✅\");",
"          loadHome();",
"        }).catch(function(e){",
"          authSetError(\"Signup failed: \" + e.message);",
"        });",
"      };",
"    }",
"",
"    var switchToLogin = $(\"authSwitchToLogin\");",
"    if (switchToLogin) {",
"      switchToLogin.onclick = function(){ authOpen(\"login\"); };",
"    }",
"",
"    var switchToSignup = $(\"authSwitchToSignup\");",
"    if (switchToSignup) {",
"      switchToSignup.onclick = function(){ authOpen(\"signup\"); };",
"    }",
"",
"    var cancelBtn = $(\"authCancelBtn\");",
"    if (cancelBtn) {",
"      cancelBtn.onclick = function(){ authClose(); };",
"    }",
"",
"    var loginHandle = $(\"authLoginHandle\");",
"    var loginPassword = $(\"authLoginPassword\");",
"    if (loginHandle) {",
"      loginHandle.onkeydown = function(e){",
"        if (e && e.key === \"Enter\") {",
"          e.preventDefault();",
"          if ($(\"authLoginPassword\")) $(\"authLoginPassword\").focus();",
"        }",
"      };",
"    }",
"    if (loginPassword) {",
"      loginPassword.onkeydown = function(e){",
"        if (e && e.key === \"Enter\") {",
"          e.preventDefault();",
"          if ($(\"authLoginSubmit\")) $(\"authLoginSubmit\").click();",
"        }",
"      };",
"    }",
"",
"    var signupHandle = $(\"authSignupHandle\");",
"    var signupEmail = $(\"authSignupEmail\");",
"    var signupPassword = $(\"authSignupPassword\");",
"    if (signupHandle) {",
"      signupHandle.onkeydown = function(e){",
"        if (e && e.key === \"Enter\") {",
"          e.preventDefault();",
"          if ($(\"authSignupEmail\")) $(\"authSignupEmail\").focus();",
"        }",
"      };",
"    }",
"    if (signupEmail) {",
"      signupEmail.onkeydown = function(e){",
"        if (e && e.key === \"Enter\") {",
"          e.preventDefault();",
"          if ($(\"authSignupPassword\")) $(\"authSignupPassword\").focus();",
"        }",
"      };",
"    }",
"    if (signupPassword) {",
"      signupPassword.onkeydown = function(e){",
"        if (e && e.key === \"Enter\") {",
"          e.preventDefault();",
"          if ($(\"authSignupSubmit\")) $(\"authSignupSubmit\").click();",
"        }",
"      };",
"    }",
"  }",
"",

