function manifestJson(request) {
  const body = {
    name: "SaySay Music",
    short_name: "SaySay Music",
    description: "Educational music streaming platform — Education through melody.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#050505",
    theme_color: "#ffbf00",
    categories: ["music", "education", "entertainment"],
    icons: [
      {
        src: "/app-icon.svg",
        sizes: "any",
        type: "image/svg+xml",
        purpose: "any maskable"
      }
    ]
  };

  return new Response(JSON.stringify(body, null, 2), {
    status: 200,
    headers: {
      "Content-Type": "application/manifest+json; charset=utf-8",
      "Cache-Control": "no-store"
    }
  });
}

function serviceWorkerJs(request) {
  const js = [
    "const SS_CACHE = 'saysay-pwa-shell-v3';",
    "const SS_URLS = ['/', '/manifest.json', '/app-icon.svg'];",
    "",
    "self.addEventListener('install', function(event){",
    "  event.waitUntil(",
    "    caches.open(SS_CACHE).then(function(cache){",
    "      return cache.addAll(SS_URLS);",
    "    }).then(function(){",
    "      return self.skipWaiting();",
    "    })",
    "  );",
    "});",
    "",
    "self.addEventListener('activate', function(event){",
    "  event.waitUntil(",
    "    caches.keys().then(function(keys){",
    "      return Promise.all(keys.map(function(key){",
    "        if (key !== SS_CACHE) return caches.delete(key);",
    "      }));",
    "    }).then(function(){",
    "      return self.clients.claim();",
    "    })",
    "  );",
    "});",
    "",
    "self.addEventListener('fetch', function(event){",
    "  const req = event.request;",
    "  const url = new URL(req.url);",
    "",
    "  if (req.method !== 'GET') return;",
    "",
    "  if (url.origin !== self.location.origin) return;",
    "",
    "  if (url.pathname === '/sw.js') return;",
    "",
    "  if (url.pathname.startsWith('/api/')) return;",
    "",
    "  if (req.mode === 'navigate') {",
    "    event.respondWith(",
    "      fetch(req).then(function(res){",
    "        const copy = res.clone();",
    "        caches.open(SS_CACHE).then(function(cache){ cache.put('/', copy); });",
    "        return res;",
    "      }).catch(function(){",
    "        return caches.match('/');",
    "      })",
    "    );",
    "    return;",
    "  }",
    "",
    "  event.respondWith(",
    "    caches.match(req).then(function(hit){",
    "      if (hit) return hit;",
    "      return fetch(req).then(function(res){",
    "        const copy = res.clone();",
    "        caches.open(SS_CACHE).then(function(cache){",
    "          cache.put(req, copy);",
    "        });",
    "        return res;",
    "      });",
    "    })",
    "  );",
    "});"
     ].join('\n');

  return new Response(js, {
    status: 200,
    headers: {
      "Content-Type": "application/javascript; charset=utf-8",
      "Cache-Control": "no-store"
    }
  });
}

